import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';

interface VoiceConciergeProps {
  onClose: () => void;
}

const RESORT_IMAGES: Record<string, { name: string; location: string; url: string }> = {
