import React, { useState, useRef } from 'react';
import { GoogleGenAI } from "@google/genai";

interface VideoAnimatorProps {
  onClose: () => void;
}

const VideoAnimator: React.FC<VideoAnimatorProps> = ({ onClose }) => {
  const [step, setStep] = useState<'upload' | 'generating' | 'result'>('upload');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [prompt, setPrompt] = useState('A cinematic sweeping shot of a luxury holiday resort at sunset, gentle movement of palm trees and ocean waves.');
  const [aspectRatio, setAspectRatio] = useState<'16:9' | '9:16'>('16:9');
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [loadingMessage, setLoadingMessage] = useState('Initiating dream visualization...');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const loadingMessages = [
    'Analyzing your perfect holiday vision...',
    'Synthesizing luxury atmospheres...',
    'Rendering high-fidelity vacation memories...',
    'Perfecting the gentle sway of the ocean...',
    'Almost there! Wrapping up your cinematic escape...'
  ];

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const startGeneration = async () => {
    const aistudio = (window as any).aistudio;

    // For Veo models, try to use aistudio selector if available
    if (aistudio) {
        const hasKey = await aistudio.hasSelectedApiKey();
        if (!hasKey) {
            await aistudio.openSelectKey();
        }
    }

    setStep('generating');
    let msgIndex = 0;
    const interval = setInterval(() => {
      setLoadingMessage(loadingMessages[msgIndex % loadingMessages.length]);
      msgIndex++;
    }, 12000);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const base64Data = selectedImage?.split(',')[1] || '';

      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: prompt,
        image: {
          imageBytes: base64Data,
          mimeType: 'image/png',
        },
        config: {
          numberOfVideos: 1,
          resolution: '720p',
          aspectRatio: aspectRatio
        }
      });

      while (!operation.done) {
        await new Promise(resolve => setTimeout(resolve, 10000));
        operation = await ai.operations.getVideosOperation({ operation: operation });
      }

      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      if (downloadLink) {
        const videoResponse = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
        const videoBlob = await videoResponse.blob();
        setVideoUrl(URL.createObjectURL(videoBlob));
        setStep('result');
      } else {
        throw new Error("No video link returned.");
      }

    } catch (error: any) {
      console.error("Veo Error:", error);
      if (error.message?.includes("Requested entity was not found") && aistudio) {
        await aistudio.openSelectKey();
      } else {
        alert("Something went wrong with the generation. Please ensure you have a valid API key.");
      }
      setStep('upload');
    } finally {
      clearInterval(interval);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 md:p-8">
      <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-xl" onClick={onClose}></div>

      <div className="relative bg-white rounded-3xl w-full max-w-4xl max-h-[90vh] overflow-hidden shadow-2xl flex flex-col">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center">
          <h2 className="text-2xl font-bold text-slate-900">Dream Visionizer <span className="text-xs bg-blue-100 text-blue-600 px-2 py-0.5 rounded-full ml-2 uppercase tracking-widest font-bold tracking-widest">Veo 3.1</span></h2>
          <button onClick={onClose} className="w-10 h-10 rounded-full hover:bg-slate-100 flex items-center justify-center transition-colors">
            <i className="fas fa-times text-slate-400"></i>
          </button>
        </div>

        <div className="flex-grow overflow-y-auto p-8">
          {step === 'upload' && (
            <div className="max-w-2xl mx-auto space-y-8">
              <div className="text-center">
                <p className="text-slate-600 mb-2">Upload a photo to see it transformed into a cinematic holiday escape.</p>
                <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener noreferrer" className="text-xs text-blue-600 hover:underline">Requires a paid Google Cloud Project API Key</a>
              </div>

              <div 
                onClick={() => fileInputRef.current?.click()}
                className={`relative border-2 border-dashed rounded-2xl aspect-video flex flex-col items-center justify-center cursor-pointer transition-all ${selectedImage ? 'border-blue-400 bg-blue-50' : 'border-slate-200 hover:border-blue-400 hover:bg-slate-50'}`}
              >
                {selectedImage ? (
                  <img src={selectedImage} alt="Preview" className="w-full h-full object-cover rounded-2xl" />
                ) : (
                  <>
                    <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center text-2xl mb-4">
                      <i className="fas fa-cloud-upload-alt"></i>
                    </div>
                    <p className="font-bold text-slate-700">Click to upload your image</p>
                  </>
                )}
                <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileChange} accept="image/*" />
              </div>

              {selectedImage && (
                <div className="space-y-6 animate-[fadeInUp_0.5s_ease-out]">
                  <div>
                    <label className="block text-xs font-bold uppercase tracking-widest text-slate-400 mb-2">Atmosphere Prompt</label>
                    <textarea 
                      value={prompt}
                      onChange={(e) => setPrompt(e.target.value)}
                      className="w-full bg-slate-50 border border-slate-200 rounded-xl p-4 text-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-400 h-24"
                    />
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    {(['16:9', '9:16'] as const).map(ratio => (
                      <button
                        key={ratio}
                        onClick={() => setAspectRatio(ratio)}
                        className={`py-3 rounded-xl font-bold border-2 transition-all ${aspectRatio === ratio ? 'bg-blue-600 border-blue-600 text-white' : 'bg-white border-slate-100 text-slate-600 hover:bg-slate-50'}`}
                      >
                        {ratio} {ratio === '16:9' ? 'Landscape' : 'Portrait'}
                      </button>
                    ))}
                  </div>

                  <button 
                    onClick={startGeneration}
                    className="w-full py-5 bg-blue-600 text-white rounded-2xl font-bold text-lg hover:bg-blue-700 transition-all shadow-xl shadow-blue-500/20 active:scale-[0.98]"
                  >
                    Animate My Vision
                  </button>
                </div>
              )}
            </div>
          )}

          {step === 'generating' && (
            <div className="flex flex-col items-center justify-center py-20 text-center space-y-8 animate-pulse">
              <div className="relative w-32 h-32">
                <div className="absolute inset-0 border-4 border-blue-100 rounded-full"></div>
                <div className="absolute inset-0 border-4 border-t-blue-600 rounded-full animate-spin"></div>
                <div className="absolute inset-0 flex items-center justify-center text-3xl text-blue-600">
                  <i className="fas fa-magic"></i>
                </div>
              </div>
              <h3 className="text-2xl font-bold text-slate-900">{loadingMessage}</h3>
            </div>
          )}

          {step === 'result' && videoUrl && (
            <div className="max-w-3xl mx-auto space-y-8 text-center animate-[fadeIn_1s_ease-out]">
              <div className="rounded-3xl overflow-hidden shadow-2xl bg-black aspect-video flex items-center justify-center">
                <video 
                  src={videoUrl} 
                  autoPlay 
                  loop 
                  controls 
                  className={`max-w-full max-h-full ${aspectRatio === '9:16' ? 'h-full w-auto' : 'w-full h-auto'}`}
                />
              </div>
              <div className="flex flex-col md:flex-row items-center justify-center gap-4">
                <a 
                  href={videoUrl} 
                  download="dream-holiday.mp4"
                  className="bg-blue-600 text-white px-8 py-4 rounded-full font-bold flex items-center gap-2 hover:bg-blue-700 transition-all"
                >
                  <i className="fas fa-download"></i> Download Video
                </a>
                <button 
                  onClick={() => setStep('upload')}
                  className="bg-slate-100 text-slate-700 px-8 py-4 rounded-full font-bold hover:bg-slate-200 transition-all"
                >
                  Create Another
                </button>
              </div>
            </div>
          )}
        </div>
      </div>

      <style dangerouslySetInnerHTML={{ __html: `
        @keyframes fadeInUp {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes fadeIn {
          from { opacity: 0; }
          to { opacity: 1; }
        }
      `}} />
    </div>
  );
};

export default VideoAnimator;

import React, { useState, useEffect, useRef } from 'react';

interface FooterProps {
  isAdmin?: boolean;
  onToggleAdmin?: () => void;
  onLegalClick?: (type: 'privacy' | 'terms') => void;
}

const BRAND_CONFIG_KEY = 'dream_it_brand_config_v2';
const SOCIAL_STORAGE_KEY = 'dream_it_social_links_v2';
const scriptURL = 'https://script.google.com/macros/s/AKfycbw82oR186SCMQlO1lCTrq37t7_NNjxIwEN90_kxm48AJiuxwT-cl48PEKr1LqNmgKir/exec';

const DEFAULT_SOCIALS = {
  facebook: 'https://www.facebook.com/DreamVacationsSA/',
  instagram: 'https://www.instagram.com/dreamvacations_sa/',
  tiktok: 'https://www.tiktok.com/@dreamvacations_sa'
};

const Footer: React.FC<FooterProps> = ({ isAdmin = false, onToggleAdmin, onLegalClick }) => {
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [showAdminSettings, setShowAdminSettings] = useState(false);
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [agentPhoto, setAgentPhoto] = useState<string | null>(null);
  const agentFileInputRef = useRef<HTMLInputElement>(null);

  // High-priority initialization to avoid flicker
  const [socialLinks, setSocialLinks] = useState(() => {
    try {
      const saved = localStorage.getItem(SOCIAL_STORAGE_KEY);
      return saved ? JSON.parse(saved) : DEFAULT_SOCIALS;
    } catch (e) {
      return DEFAULT_SOCIALS;
    }
  });

  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const [email, setEmail] = useState('');
  const [subStatus, setSubStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');
  const [subError, setSubError] = useState('');

  useEffect(() => {
    const loadConfig = () => {
      const savedBrand = localStorage.getItem(BRAND_CONFIG_KEY);
      if (savedBrand) {
        try {
          const config = JSON.parse(savedBrand);
          setAgentPhoto(config.agentPhoto || null);
        } catch (e) {}
      }

      const savedSocial = localStorage.getItem(SOCIAL_STORAGE_KEY);
      if (savedSocial) {
        try {
          setSocialLinks(JSON.parse(savedSocial));
        } catch (e) {}
      }
    };

    loadConfig();
    window.addEventListener('storage', loadConfig);
    return () => window.removeEventListener('storage', loadConfig);
  }, []);

  const handleAdminClick = () => {
    if (isAdmin) {
      if (onToggleAdmin) onToggleAdmin();
    } else {
      setShowLoginModal(true);
    }
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (password === '072111') {
      if (onToggleAdmin) onToggleAdmin();
      setShowLoginModal(false);
      setPassword('');
      setError('');
    } else {
      setError('Invalid admin credentials.');
    }
  };

  const handleAgentPhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 1500000) {
        alert("This photo is too large. Please use a smaller image.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = reader.result as string;
        setAgentPhoto(base64);

        const savedBrand = localStorage.getItem(BRAND_CONFIG_KEY);
        let config = savedBrand ? JSON.parse(savedBrand) : {};
        config.agentPhoto = base64;
        localStorage.setItem(BRAND_CONFIG_KEY, JSON.stringify(config));
        window.dispatchEvent(new Event('storage'));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSocialChange = (key: keyof typeof DEFAULT_SOCIALS, value: string) => {
    setSocialLinks((prev: any) => ({ ...prev, [key]: value }));
    setSaveStatus('idle');
  };

  const saveSocialLinks = () => {
    setSaveStatus('saving');
    localStorage.setItem(SOCIAL_STORAGE_KEY, JSON.stringify(socialLinks));

    setTimeout(() => {
      setSaveStatus('saved');
      window.dispatchEvent(new Event('storage'));
      setTimeout(() => {
        setShowAdminSettings(false);
        setSaveStatus('idle');
      }, 1500);
    }, 400);
  };

  const handleSubscribe = async (e: React.FormEvent) => {
    e.preventDefault();
    setSubError('');
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      setSubError('Valid email required.');
      return;
    }
    setSubStatus('loading');
    try {
      const payload = {
        name: 'Subscriber',
        email: email,
        interest: 'Newsletter',
        source: 'Footer',
        timestamp: new Date().toLocaleString(),
      };
      await fetch(scriptURL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify(payload),
      });
      setSubStatus('success');
      setEmail('');
    } catch (err) {
      setSubStatus('error');
      setSubError('Subscription failed.');
    }
  };

  return (
    <footer className="bg-slate-900 text-slate-400 py-20 border-t border-slate-800 relative">
      <div className="max-w-7xl mx-auto px-6">
        <div className="grid md:grid-cols-2 gap-16 mb-20">
          <div className="max-w-md">
             <div className="flex flex-col items-center md:items-start group">
              <div className="flex items-center gap-6 mb-4">
                <span className="text-[10px] font-bold text-white tracking-[0.4em] uppercase opacity-40 text-center md:text-left">Accredited Agent</span>
                {isAdmin && (
                  <button 
                    onClick={() => agentFileInputRef.current?.click()}
                    className="w-8 h-8 rounded-full bg-white/5 border border-white/10 flex items-center justify-center hover:bg-white/10 hover:text-white transition-all opacity-0 group-hover:opacity-100"
                  >
                    <i className="fas fa-camera text-[10px]"></i>
                  </button>
                )}
              </div>

              <div className="relative mb-6">
                {agentPhoto ? (
                  <img 
                    src={agentPhoto} 
                    alt="Agent" 
                    className="h-24 w-auto object-contain rounded-lg filter grayscale opacity-60 hover:grayscale-0 hover:opacity-100 transition-all duration-700 cursor-pointer"
                  />
                ) : (
                  isAdmin && (
                    <div 
                      onClick={() => agentFileInputRef.current?.click()}
                      className="h-20 w-32 border-2 border-dashed border-white/10 rounded-xl flex flex-col items-center justify-center cursor-pointer hover:border-white/30"
                    >
                      <i className="fas fa-plus text-white/20 text-xl mb-1"></i>
                      <span className="text-[8px] font-bold uppercase text-white/20">Photo</span>
                    </div>
                  )
                )}
                <input type="file" ref={agentFileInputRef} onChange={handleAgentPhotoUpload} className="hidden" accept="image/*" />
              </div>

              <p className="text-sm leading-relaxed text-slate-400 max-w-sm text-center md:text-left">
                Your lifetime ticket to investing more time into your holidays, when you need them, and where you want them.
              </p>
            </div>
          </div>

          <div className="max-w-sm ml-auto w-full">
            <h4 className="text-white font-bold mb-6 text-sm uppercase tracking-widest text-center md:text-left">Newsletter</h4>
            {subStatus === 'success' ? (
              <div className="bg-blue-600/10 border border-blue-500/30 rounded-xl p-6 text-center">
                <i className="fas fa-check text-blue-500 mb-2"></i>
                <h5 className="text-white font-bold text-sm">Subscribed</h5>
              </div>
            ) : (
              <form onSubmit={handleSubscribe} className="space-y-3">
                <div className="flex w-full group relative">
                  <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="Email address" className="bg-slate-800 border border-slate-700 rounded-l-xl px-5 py-3 w-full focus:ring-1 focus:ring-blue-500 text-white text-sm outline-none transition-all" />
                  <button type="submit" disabled={subStatus === 'loading'} className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-r-xl transition-colors min-w-[60px]">
                    {subStatus === 'loading' ? <i className="fas fa-circle-notch animate-spin"></i> : <i className="fas fa-paper-plane"></i>}
                  </button>
                </div>
                {subError && <p className="text-red-400 text-[11px]">{subError}</p>}
              </form>
            )}
          </div>
        </div>

        <div className="pt-8 border-t border-slate-800/50 flex flex-col md:flex-row justify-between items-center text-[11px] gap-6 relative">
          <div className="flex items-center gap-8">
            <p className="text-slate-500 uppercase tracking-wider font-medium">© 2026. DREAM IT MARKETING.</p>
            <div className="flex space-x-6">
              <button onClick={() => onLegalClick?.('privacy')} className="hover:text-white">Privacy</button>
              <button onClick={() => onLegalClick?.('terms')} className="hover:text-white">Terms</button>
            </div>
          </div>

          <div className="flex items-center gap-8">
            <div className="flex items-center space-x-5 text-base">
              <a href={socialLinks.facebook} target="_blank" rel="noopener noreferrer" className="text-slate-500 hover:text-white transition-colors"><i className="fab fa-facebook-f"></i></a>
              <a href={socialLinks.instagram} target="_blank" rel="noopener noreferrer" className="text-slate-500 hover:text-white transition-colors"><i className="fab fa-instagram"></i></a>
              <a href={socialLinks.tiktok} target="_blank" rel="noopener noreferrer" className="text-slate-500 hover:text-white transition-colors"><i className="fab fa-tiktok"></i></a>

              {isAdmin && (
                <div className="relative">
                  <button 
                    onClick={() => setShowAdminSettings(!showAdminSettings)} 
                    className={`w-8 h-8 rounded-full flex items-center justify-center transition-all ${showAdminSettings ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-500 hover:text-white'}`}
                  >
                    <i className="fas fa-cog"></i>
                  </button>

                  {showAdminSettings && (
                    <div className="absolute bottom-full right-0 mb-4 bg-white rounded-2xl shadow-2xl p-6 border border-slate-100 min-w-[280px] z-[70] animate-[fadeInUp_0.3s_ease-out]">
                      <h4 className="text-[10px] font-bold uppercase tracking-widest text-slate-400 mb-6 flex items-center gap-2">
                        <i className="fas fa-link text-blue-500"></i> Social Media Profiles
                      </h4>

                      <div className="space-y-5 mb-8">
                        {(['facebook', 'instagram', 'tiktok'] as const).map(platform => (
                          <div key={platform} className="space-y-1.5">
                            <label className="text-[9px] font-bold uppercase text-slate-500 flex items-center gap-2">
                              <i className={`fab fa-${platform === 'facebook' ? 'facebook-square' : platform}`}></i> {platform} URL
