    url: 'https://images.unsplash.com/photo-1580619305218-8423a7ef79b4?auto=format&fit=crop&q=80&w=1200' 
  },
  'safari': { 
    name: 'The Safari Collection', 
    location: 'South African Bushveld', 
    url: 'https://images.unsplash.com/photo-1547471080-7cc2caa01a7e?auto=format&fit=crop&q=80&w=1200' 
  },
  'coastal': { 
    name: 'Coastal Escapes', 
    location: 'KwaZulu-Natal & Cape Shores', 
    url: 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&q=80&w=1200' 
  }
};

const displayVisualsFn: FunctionDeclaration = {
  name: 'display_resort_visuals',
  parameters: {
    type: Type.OBJECT,
    description: 'Display an image of a specific resort or holiday category to the user.',
    properties: {
      destination_id: {
        type: Type.STRING,
        description: 'The slug of the resort or category to show. Options: mount-amanzi, finfoot, alpine-heath, breakers, blue-marlin, peninsula, safari, coastal',
      },
    },
    required: ['destination_id'],
  },
};

const VoiceConcierge: React.FC<VoiceConciergeProps> = ({ onClose }) => {
  const [sessionState, setSessionState] = useState<'idle' | 'connecting' | 'active' | 'error'>('idle');
  const [status, setStatus] = useState('Elena is resting...');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [currentVisual, setCurrentVisual] = useState<typeof RESORT_IMAGES['mount-amanzi'] | null>(null);

  const audioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionRef = useRef<any>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const decode = (base64: string) => {
    try {
      const binaryString = atob(base64);
      const bytes = new Uint8Array(binaryString.length);
      for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
      return bytes;
    } catch (e) { return new Uint8Array(0); }
  };
  const encode = (bytes: Uint8Array) => {
    let binary = '';
    for (let i = 0; i < bytes.byteLength; i++) binary += String.fromCharCode(bytes[i]);
    return btoa(binary);
  };
  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number) => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
    return buffer;
  };
  const createBlob = (data: Float32Array) => ({
    data: encode(new Uint8Array(new Int16Array(data.map(v => v * 32768)).buffer)),
    mimeType: 'audio/pcm;rate=16000',
  });

  const cleanup = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close(); sessionRef.current = null; }
    if (audioContextRef.current) { audioContextRef.current.close(); audioContextRef.current = null; }
    if (outputAudioContextRef.current) { outputAudioContextRef.current.close(); outputAudioContextRef.current = null; }
    if (streamRef.current) { streamRef.current.getTracks().forEach(track => track.stop()); streamRef.current = null; }
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    setSessionState('idle');
    setIsSpeaking(false);
  }, []);

  const startSession = async () => {
    cleanup();
    setError(null);
    setSessionState('connecting');
    setStatus('Elena is waking up...');

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey || apiKey === 'undefined') {
        throw new Error("API Key not found. Please ensure your key is active.");
      }

      setStatus('Accessing Microphone...');
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true }).catch(() => {
        throw new Error("Microphone access blocked. Click the 'lock' icon in your address bar to allow.");
      });
      streamRef.current = stream;

      setStatus('Initializing Live Stream...');
      const ai = new GoogleGenAI({ apiKey: apiKey });
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            setSessionState('active');
            setStatus('Elena is ready to talk.');
            if (audioContextRef.current) {
              const source = audioContextRef.current.createMediaStreamSource(stream);
              const scriptProcessor = audioContextRef.current.createScriptProcessor(4096, 1, 1);
              scriptProcessor.onaudioprocess = (e) => {
                const pcmBlob = createBlob(e.inputBuffer.getChannelData(0));
                sessionPromise.then(s => s?.sendRealtimeInput({ media: pcmBlob }));
              };
              source.connect(scriptProcessor);
              scriptProcessor.connect(audioContextRef.current.destination);
            }
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.toolCall && message.toolCall.functionCalls) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'display_resort_visuals') {
                  const id = (fc.args as any).destination_id;
                  if (RESORT_IMAGES[id]) setCurrentVisual(RESORT_IMAGES[id]);
                  sessionPromise.then(s => s?.sendToolResponse({
                    functionResponses: { id: fc.id, name: fc.name, response: { result: "Image displayed" } }
                  }));
                }
              }
            }

            const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (base64Audio && outputAudioContextRef.current) {
              setIsSpeaking(true);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputAudioContextRef.current.currentTime);
              const buffer = await decodeAudioData(decode(base64Audio), outputAudioContextRef.current, 24000, 1);
              const source = outputAudioContextRef.current.createBufferSource();
              source.buffer = buffer;
              source.connect(outputAudioContextRef.current.destination);
              source.onended = () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              };
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }

            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setIsSpeaking(false);
            }
          },
          onerror: (e: any) => { 
            console.error(e);
            setError("Connection failed. Your project may not support Gemini 2.5 Live."); 
            setSessionState('error');
          },
          onclose: () => { setSessionState('idle'); }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          tools: [{ functionDeclarations: [displayVisualsFn] }],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
          systemInstruction: 'You are Elena, the elite Dream Vacation Club concierge. You help users plan luxury escapes and display visuals using function calls.',
        },
      });

      sessionRef.current = await sessionPromise;
    } catch (err: any) {
      setError(err.message || "Failed to wake Elena.");
      setSessionState('error');
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-950/98 backdrop-blur-3xl" onClick={onClose}></div>

      <div className="relative w-full max-w-4xl flex flex-col items-center">
        <button onClick={onClose} className="absolute -top-16 right-0 w-12 h-12 bg-white/10 hover:bg-white/20 rounded-full flex items-center justify-center text-white transition-all z-50">
          <i className="fas fa-times"></i>
        </button>

        <div className="w-full grid lg:grid-cols-2 gap-12 items-center">

          <div className="relative aspect-square rounded-[3rem] overflow-hidden shadow-2xl bg-slate-900 border border-white/10 flex items-center justify-center">
            {currentVisual ? (
              <div className="absolute inset-0 animate-[fadeIn_0.8s_ease-out]">
                <img src={currentVisual.url} alt={currentVisual.name} className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent"></div>
                <div className="absolute bottom-8 left-8 right-8 p-6 bg-white/10 backdrop-blur-xl border border-white/20 rounded-2xl">
                  <h3 className="text-white text-xl font-bold serif">{currentVisual.name}</h3>
                  <p className="text-blue-300 text-[10px] font-bold uppercase tracking-widest">{currentVisual.location}</p>
                </div>
              </div>
            ) : (
              <div className="text-center space-y-6 opacity-20">
                <i className="fas fa-microphone-alt text-7xl text-white"></i>
                <p className="text-white text-[10px] uppercase tracking-[0.4em] font-black">Waiting for Elena...</p>
              </div>
            )}

            {isSpeaking && (
              <div className="absolute top-8 right-8 flex items-center gap-1.5">
                {[...Array(4)].map((_, i) => (
                  <div key={i} className="w-1.5 h-6 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: `${i * 0.1}s` }}></div>
                ))}
              </div>
            )}
          </div>

          <div className="text-center lg:text-left space-y-10">
            <div className="space-y-4">
              <h2 className="text-white text-6xl md:text-8xl font-bold serif tracking-tight">Meet Elena</h2>
              <p className="text-blue-400 font-bold uppercase tracking-[0.4em] text-xs">Dream Vacation Club Concierge</p>
            </div>

            <div className="space-y-8">
              <div className="flex flex-col lg:items-start items-center gap-6">
                <div className="bg-white/5 border border-white/10 px-6 py-4 rounded-2xl inline-block backdrop-blur-md">
                  <span className="text-white/80 text-sm flex items-center gap-4 font-medium">
                    <span className={`w-3 h-3 rounded-full ${sessionState === 'active' ? 'bg-green-500 shadow-[0_0_15px_rgba(34,197,94,0.6)] animate-pulse' : sessionState === 'connecting' ? 'bg-amber-500 animate-spin' : 'bg-red-500'}`}></span>
                    {status}
                  </span>
                </div>

                {sessionState !== 'active' && (
                  <button 
                    onClick={startSession} 
                    className={`px-10 py-5 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl text-xs font-black uppercase tracking-widest transition-all shadow-2xl shadow-blue-600/30 active:scale-95 ${sessionState === 'connecting' ? 'opacity-50 cursor-not-allowed' : ''}`}
                  >
                    {sessionState === 'connecting' ? 'Connecting...' : 'Wake Up Elena'}
                  </button>
                )}
              </div>

              <div className="flex items-end justify-center lg:justify-start gap-2 h-12">
                {[...Array(20)].map((_, i) => (
                  <div key={i} className={`w-1 rounded-full bg-blue-500/30 transition-all duration-200 ${isSpeaking ? 'bg-blue-400' : ''}`} style={{ height: sessionState === 'active' ? (isSpeaking ? `${Math.random() * 100 + 20}%` : '8px') : '4px' }}></div>
                ))}
              </div>
            </div>

            {error && (
              <div className="p-6 bg-red-500/10 border border-red-500/20 rounded-2xl max-w-sm">
                <p className="text-red-400 text-[10px] font-black uppercase tracking-widest mb-2">Technical Block:</p>
                <p className="text-red-200 text-xs leading-relaxed">{error}</p>
              </div>
            )}

            <p className="text-white/30 text-sm max-w-md leading-relaxed italic border-l-4 border-blue-500/20 pl-6">
              "Tell me what your perfect day looks like, and I'll show you exactly where that memory is waiting to be made."
            </p>
          </div>
        </div>
      </div>
      <style dangerouslySetInnerHTML={{ __html: `
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
      `}} />
    </div>
  );
};

export default VoiceConcierge;

